<script setup lang="ts">
import { ref } from 'vue'
import { commit, db } from '../store'
import type { Room } from '../domain/types'
import Icon from '../components/Icon.vue'
import DemandCalendar from '../components/DemandCalendar.vue'
const roomDraft = ref(db.value.rooms.map(r => ({ ...r })))
async function saveRoom(room: Room) { await commit('已保存房间资料', room.name, d => { const at = d.rooms.findIndex(r => r.id === room.id); if (!room.name.trim()) throw new Error('请填写房间名称'); d.rooms[at] = { ...room } }) }
async function toggleShift(id: string, event: Event) { const enabled = (event.target as HTMLInputElement).checked; await commit('已更新班次开关', id, d => { d.shifts.find(s => s.id === id)!.enabled = enabled }) }
</script>
<template><section class="page-heading"><div><h1>房间与班次</h1><p>四个房间，八类班次。房间决定颜色，班次决定安排。</p></div><span class="pill success">每班固定2人</span></section><div class="callout green"><Icon name="info" :size="20" /><div><strong>配置更改用于下一次生成</strong><p>已有版本保留当时的需求快照；停用班次或调整每日开关后，请重新生成目标月。</p></div></div><div class="room-config-grid"><section v-for="room in roomDraft" :key="room.id" class="panel room-config"><header :style="{ background: room.color, color: room.ink }"><Icon :name="room.id === 'photon' ? 'sparkle' : 'rooms'" :size="25" /><span>{{ db.rooms.find(r => r.id === room.id)?.name }}</span><small>{{ db.shifts.filter(s => s.roomId === room.id).length }}类班次</small></header><div class="room-config-body"><div class="form-grid"><label class="field">房间名称<input v-model="room.name" maxlength="30" /></label><label class="field">显示颜色<div class="color-control"><input v-model="room.color" type="color" :aria-label="`${room.name}显示颜色`" /><span>{{ room.color.toUpperCase() }}</span></div></label></div><div v-for="shift in db.shifts.filter(s => s.roomId === room.id)" :key="shift.id" class="shift-config-row"><span><strong>{{ shift.category }}班</strong><small>{{ shift.id }}</small></span><span class="muted">2人 / 班</span><label class="switch"><input type="checkbox" :checked="shift.enabled" :aria-label="`启用${room.name}${shift.category}班`" @change="toggleShift(shift.id,$event)" /><i></i></label></div><button class="button secondary full-width" @click="saveRoom(room)">保存房间资料</button></div></section></div><DemandCalendar /></template>
